// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 ts, uint256 blk, address actor) public {
        ts = bound(ts, 1, type(uint256).max / 2);
        blk = bound(blk, 1, type(uint256).max / 2);
        vm.assume(ts != blk);
        vm.assume(actor != address(0) && actor != address(c));

        vm.warp(ts);
        vm.roll(blk);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // The reference contract records the calling block's timestamp;
        // the mutant records the block number instead, which differs here.
        assertEq(c.pastBlockTime(), ts);
    }
}
